document.addEventListener('DOMContentLoaded', function () {
  AOS.init({
    duration: 800,
    easing: 'ease-in-out',
    once: true,
    disable: window.innerWidth < 768
  });


  window.addEventListener('scroll', function () {
    const navbar = document.querySelector('.navbar');
    const backToTop = document.getElementById('backToTop');

    navbar.classList.toggle('scrolled', window.scrollY > 50);
    backToTop.classList.toggle('active', window.scrollY > 300);
  });

  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      e.preventDefault();
      const target = document.querySelector(this.getAttribute('href'));
      if (target) {
        window.scrollTo({
          top: target.offsetTop - 70,
          behavior: 'smooth'
        });
      }
    });
  });

  const navbarToggler = document.querySelector('.navbar-toggler');
  const navbarCollapse = document.querySelector('.navbar-collapse');
  const navLinks = document.querySelectorAll('.nav-link');

  navLinks.forEach(link => {
    link.addEventListener('click', () => {
      if (navbarCollapse.classList.contains('show')) {
        const bsCollapse = new bootstrap.Collapse(navbarCollapse);
        bsCollapse.hide();
        document.body.style.overflow = '';
      }
    });
  });

  navbarToggler.addEventListener('click', function () {
    document.body.style.overflow = (this.getAttribute('aria-expanded') === 'true') ? 'hidden' : '';
  });

  document.addEventListener('click', function (e) {
    if (!navbarToggler.contains(e.target) &&
      !navbarCollapse.contains(e.target) &&
      navbarCollapse.classList.contains('show')) {
      const bsCollapse = new bootstrap.Collapse(navbarCollapse);
      bsCollapse.hide();
      document.body.style.overflow = '';
    }
  });

  // Hero section slider logic
  const heroImages = [
    'images/slider6.webp',
    'images/slider7.webp',
    'images/slider8.webp',
  ];
  const heroTexts = [
    { title: "Welcome to Aromaticroot Queen", subtitle: "Experience the purity of herbal luxury" },
    { title: "Eco-Friendly & Sustainable", subtitle: "Vetiver products that support a green future" },
    { title: "Premium Vetiver Products", subtitle: "Crafted with care, love, and purity" }
  ];

  let currentIndex = 0;
  const heroBg = document.querySelector('.hero-background');
  const heroTitle = document.querySelector('.hero-title');
  const heroSubtitle = document.querySelector('.hero-subtitle');
  const heroContent = document.querySelector('.hero-content');
  const heroSection = document.querySelector('.hero-section');

  heroBg.style.backgroundImage = `url(${heroImages[0]})`;
  heroTitle.textContent = heroTexts[0].title;
  heroSubtitle.textContent = heroTexts[0].subtitle;

  gsap.fromTo(heroContent, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.5, ease: "power1.out" });

 function changeHeroBackground() {
  currentIndex = (currentIndex + 1) % heroImages.length;

  const nextImage = heroImages[currentIndex];
  const nextTitle = heroTexts[currentIndex].title;
  const nextSubtitle = heroTexts[currentIndex].subtitle;

  // Preload the next image to avoid flash/blink
  const img = new Image();
  img.src = nextImage;

  img.onload = () => {
    // Fade out text first
    const tl = gsap.timeline();

    tl.to(heroContent, {
      duration: 0.5,
      opacity: 0,
      y: 30,
      ease: "power2.inOut",
      onComplete: () => {
        // Update content AFTER fade-out
        heroBg.style.backgroundImage = `url(${nextImage})`;
        heroTitle.textContent = nextTitle;
        heroSubtitle.textContent = nextSubtitle;
      }
    });

    // Then fade text back in
    tl.to(heroContent, {
      duration: 0.6,
      opacity: 1,
      y: 0,
      ease: "power2.out"
    });
  };
}


  let heroSliderInterval = setInterval(changeHeroBackground, 3900);
  heroSection.addEventListener('mouseenter', () => clearInterval(heroSliderInterval));
  heroSection.addEventListener('mouseleave', () => {
    heroSliderInterval = setInterval(changeHeroBackground, 5000);
  });

  const footerElements = document.querySelectorAll('.footer-animate');
  const footerObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
      }
    });
  }, { threshold: 0.1 });
  footerElements.forEach(el => footerObserver.observe(el));

  // Active nav link based on scroll position
  const sections = document.querySelectorAll('section');
  function updateActiveNav() {
    let current = '';
    sections.forEach(section => {
      const sectionTop = section.offsetTop;
      if (window.scrollY >= (sectionTop - 100)) {
        current = section.getAttribute('id');
      }
    });
    navLinks.forEach(link => {
      link.classList.remove('active');
      if (link.getAttribute('href') === `#${current}`) {
        link.classList.add('active');
      }
    });
  }
  window.addEventListener('scroll', updateActiveNav);
  updateActiveNav(); // On page load

  


  // Back to top button
  document.getElementById('backToTop').addEventListener('click', function (e) {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  // GSAP reveal animations for various cards
  gsap.utils.toArray('.value-card, .service-card, .product-card, .testimonial-card').forEach(card => {
    gsap.from(card, {
      scrollTrigger: {
        trigger: card,
        start: 'top 80%',
        toggleActions: 'play none none none'
      },
      y: 50,
      opacity: 0,
      duration: 0.8,
      ease: 'back.out(1)'
    });
  });

  gsap.to('.hero-background', {
    scrollTrigger: {
      trigger: '.hero-section',
      start: 'top top',
      end: 'bottom top',
      scrub: true
    },
    y: 100,
    ease: 'none'
  });
});

// Basic content protection
document.addEventListener("contextmenu", e => e.preventDefault());
document.addEventListener("keydown", e => {
  if (
    e.key === "F12" ||
    (e.ctrlKey && (e.key === "u" || e.key === "U")) ||
    (e.ctrlKey && e.shiftKey && ["I", "J", "C"].includes(e.key.toUpperCase()))
  ) {
    e.preventDefault();
  }
}); 